(function(){"use strict";var root=document.getElementById("PopularPosts1");if(!root)return;function webpUrl(url){if(!url||!/^https?:\/\/(?:blogger\.googleusercontent\.com|[1-4]\.bp\.blogspot\.com)\//i.test(url))return url;return url.replace(/\/((?:s\d+|w\d+)[^/?]*)(?=\/|$|\?)/i,function(full,params){return /(?:^|-)rw(?:-|$)/i.test(params)?full:"/"+params+"-rw";});}function patchImg(img){var lazy=img.getAttribute("data-src");if(lazy){var next=webpUrl(lazy);if(next!==lazy)img.setAttribute("data-src",next);}var src=img.getAttribute("src");if(src){var updated=webpUrl(src);if(updated!==src)img.setAttribute("src",updated);}}var images=root.querySelectorAll(".item-thumbnail img");for(var i=0;i<images.length;i++)patchImg(images[i]);if("MutationObserver"in window){var webpObserver=new MutationObserver(function(changes){changes.forEach(function(change){if(change.type==="attributes"&&change.target.matches(".item-thumbnail img"))patchImg(change.target);else if(change.type==="childList")change.addedNodes.forEach(function(node){if(node.nodeType!==1)return;if(node.matches&&node.matches(".item-thumbnail img"))patchImg(node);if(node.querySelectorAll)node.querySelectorAll(".item-thumbnail img").forEach(patchImg);});});});webpObserver.observe(root,{subtree:true,childList:true,attributes:true,attributeFilter:["src","data-src"]});}var nodes=Array.prototype.slice.call(root.querySelectorAll(".trending-meta[data-article-url]"));if(!nodes.length)return;var viewMap=window.SimpulTeknoTrendingViewCounts||{};function viewKey(url){try{return new URL(url,window.location.href).pathname.replace(/\/$/,"");}catch(e){return"";}}function renderViews(node){var href=node.getAttribute("data-article-url")||"";var key=viewKey(href),raw=Object.prototype.hasOwnProperty.call(viewMap,key)?viewMap[key]:viewMap[href];if(typeof raw==="number"&&Number.isFinite(raw)&&raw>=0){var label=raw>=1000?(raw/1000).toFixed(raw>=10000?0:1).replace(/\.0$/,"")+"K":String(raw);var wrap=node.querySelector(".trending-views-wrap"),value=node.querySelector(".trending-views-value");if(wrap&&value){value.textContent=label+" dilihat";wrap.classList.add("is-ready");wrap.title="Jumlah tayangan dari sumber statistik pemilik situs";wrap.removeAttribute("aria-label");}}}window.SimpulTeknoTrendingViews=function(payload){if(!payload||payload.ok!==true||!payload.viewsByPath||Object.prototype.toString.call(payload.viewsByPath)!=="[object Object]")return;viewMap=payload.viewsByPath;window.SimpulTeknoTrendingViewCounts=viewMap;nodes.forEach(renderViews);};var viewsScriptRequested=false;function requestTrendingViews(){if(viewsScriptRequested)return;viewsScriptRequested=true;var script=document.createElement("script");script.async=true;script.src="https://script.google.com/macros/s/AKfycbyYYT9oDWXm0OgbIKduaEgay83B-u8EUjjsmIIkXcijwiUgcecbhsFvvBywvb029L9bqQ/exec?format=js";script.onerror=function(){if(script.parentNode)script.parentNode.removeChild(script);};document.head.appendChild(script);}function startTrendingViews(){if("IntersectionObserver"in window){var viewsObserver=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){viewsObserver.disconnect();requestTrendingViews();}});},{rootMargin:"500px 0px"});viewsObserver.observe(root);}else requestTrendingViews();}if(document.readyState==="complete")startTrendingViews();else window.addEventListener("load",startTrendingViews,{once:true});var cache=new Map(),queue=[],active=0,maximum=2;function extractPublished(doc){var meta=doc.querySelector('meta[property="article:published_time"],meta[itemprop="datePublished"],meta[name="datePublished"]');var raw=meta&&meta.getAttribute("content");if(!raw){var abbr=doc.querySelector('.post-author abbr[title],.post-timestamp abbr[title],time.published[datetime],abbr.published[title]');raw=abbr&&(abbr.getAttribute("title")||abbr.getAttribute("datetime"));}if(!raw)return null;var date=new Date(raw);if(!Number.isFinite(date.getTime()))return null;return new Intl.DateTimeFormat("id-ID",{day:"numeric",month:"short",year:"numeric",timeZone:"Asia/Jakarta"}).format(date);}function lookup(url){if(cache.has(url))return cache.get(url);var promise=fetch(url,{credentials:"same-origin",cache:"default",redirect:"follow",priority:"low"}).then(function(response){if(!response.ok)throw new Error("HTTP "+response.status);return response.text();}).then(function(html){return extractPublished(new DOMParser().parseFromString(html,"text/html"));}).catch(function(){return null;});cache.set(url,promise);return promise;}function pump(){while(active<maximum&&queue.length){let entry=queue.shift();active++;lookup(entry.url).then(function(published){if(!published||!entry.node.isConnected)return;var wrap=entry.node.querySelector(".trending-date-wrap"),value=entry.node.querySelector(".trending-date-value");if(wrap&&value){value.textContent=published;wrap.classList.add("is-ready");}}).then(function(){active--;pump();});}}var observer="IntersectionObserver"in window?new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){observer.unobserve(entry.target);add(entry.target);}});},{rootMargin:"450px 0px"}):null;function add(node){try{var url=new URL(node.getAttribute("data-article-url")||"",location.href);if(url.origin!==location.origin)return;queue.push({node:node,url:url.href});pump();}catch(e){}}nodes.forEach(function(node){renderViews(node);if(observer)observer.observe(node);else add(node);});})();
